func (e *encoderState) propsFor(t reflect.Type) typeEncProps {
	if p, ok := builtinEncProps(t); ok {
		return p
	}
	if e.propsMemo[0].t == t {
		return e.propsMemo[0].p
	}
	for i := 1; i < len(e.propsMemo); i++ {
