			copy(e.propsMemo[1:i+1], e.propsMemo[:i])
			e.propsMemo[0] = m
			return m.p
		}
	}
	p := encPropsForType(t)
	copy(e.propsMemo[1:], e.propsMemo[:len(e.propsMemo)-1])
	e.propsMemo[0].t, e.propsMemo[0].p = t, p
	return p
